SELECT (COUNT(DISTINCT cd.mql_id) * 100.0 / COUNT(DISTINCT m.mql_id)) AS conversion_rate_percentage
FROM marketing_qualified_leads m
LEFT JOIN closed_deals cd ON m.mql_id = cd.mql_id;

